import importlib
import importlib.util
import io
import struct
import wave


def audio_module():
    assert importlib.util.find_spec("pokebench_env.audio") is not None, "audio feature missing"
    return importlib.import_module("pokebench_env.audio")


def pcm(*values):
    return b"".join(struct.pack("<hh", value, -value) for value in values)


def test_live_reader_does_not_report_nonexistent_frames_as_skipped():
    tape = audio_module().AudioTape(capacity_frames=3)
    assert tape.segment(since=-1, max_frames=2).skipped == 0
    tape.append(pcm(7))
    assert tape.segment(since=-1, max_frames=2).skipped == 0


def test_tape_serves_bounded_latest_stereo_wav_to_independent_readers():
    audio = audio_module()
    tape = audio.AudioTape(capacity_frames=3)
    tape.append(pcm(1, 2))
    first = tape.segment(since=0, max_frames=2)
    tape.append(pcm(3, 4, 5))
    slow = tape.segment(since=first.next_frame, max_frames=2)
    other = tape.segment(since=-1, max_frames=2)
    assert slow.next_frame == other.next_frame == 5
    assert slow.skipped == 1
    assert slow.wav == other.wav
    with wave.open(io.BytesIO(slow.wav)) as wav:
        assert (wav.getnchannels(), wav.getsampwidth(), wav.getframerate()) == (2, 2, 48000)
        assert wav.readframes(10) == pcm(4, 5)
    assert tape.segment(since=999, max_frames=2).next_frame == 5
    assert tape.segment(since=5, max_frames=2).wav[44:] == b""
    assert len(tape.segment(since=0, max_frames=99).wav) == 44 + 3 * 4
    with __import__("pytest").raises(ValueError):
        tape.append(b"bad")
    with __import__("pytest").raises(ValueError):
        audio.AudioTape(capacity_frames=0)
    with __import__("pytest").raises(ValueError):
        tape.segment(since=0, max_frames=0)
    tape.clear()
    cleared = tape.segment(since=0, max_frames=2)
    assert cleared.epoch == 1
    assert cleared.next_frame == 5
    assert cleared.wav[44:] == b""


class Buffer:
    def __init__(self):
        self.samples = []
        self.rates = []
        self.fail = False

    @property
    def available(self):
        return len(self.samples) // 2

    def set_rate(self, rate):
        self.rates.append(rate)

    def clear(self):
        self.samples.clear()

    def read(self, count):
        if self.fail:
            raise RuntimeError("broken sound")
        result = self.samples[: count * 2]
        del self.samples[: count * 2]
        return result


class Core:
    def __init__(self):
        self.buffer = Buffer()
        self.callbacks = []
        self.frames = 0

    def get_audio_channels(self):
        return self.buffer

    def add_frame_callback(self, callback):
        self.callbacks.append(callback)

    def run_frame(self):
        self.frames += 1
        self.buffer.samples.extend([123, -456])
        for callback in self.callbacks:
            callback()


class Emulator:
    core = None

    def initialize(self):
        self.core = Core()
        return "initialized"

    def load_state(self, value):
        self.core.buffer.samples.extend([999, 999])
        self.core.run_frame()
        return value


def test_reset_during_capture_drops_retired_core_pcm():
    audio = audio_module()

    class ResetDuringRead(Emulator):
        pass

    tape = audio.AudioTape(capacity_frames=3)
    audio.install_tap(ResetDuringRead, tape)
    emu = ResetDuringRead()
    emu.initialize()
    retired = emu.core
    read = retired.buffer.read

    def interrupted_read(count):
        values = read(count)
        emu.initialize()
        return values

    retired.buffer.read = interrupted_read
    retired.run_frame()
    assert tape.segment(-1, 3).wav[44:] == b""
    emu.core.run_frame()
    assert tape.segment(-1, 3).wav[44:] == struct.pack("<hh", 123, -456)


def test_load_flush_drops_pending_native_pcm_captured_during_buffer_clear():
    audio = audio_module()

    class Loading(Emulator):
        def load_state(self, value):
            return value

    tape = audio.AudioTape(capacity_frames=3)
    audio.install_tap(Loading, tape)
    emu = Loading()
    emu.initialize()
    buffer = emu.core.buffer
    # A frame already produced native PCM before load's final clear. No new frame
    # is generated by this injection: it only drains the pending pre-load samples.
    buffer.samples.extend([777, -777])
    clear = buffer.clear

    def capture_before_native_clear():
        emu.core.callbacks[0]()
        clear()

    buffer.clear = capture_before_native_clear
    assert emu.load_state("saved") == "saved"
    assert tape.segment(-1, 3).wav[44:] == b""
    assert buffer.available == 0
    emu.core.run_frame()
    assert tape.segment(-1, 3).wav[44:] == struct.pack("<hh", 123, -456)


def test_default_tape_capacity_and_live_window_larger_than_tiny_capacity():
    audio = audio_module()
    assert audio.AudioTape().capacity_frames == 24000
    tape = audio.AudioTape(capacity_frames=2)
    tape.append(pcm(1, 2, 3))
    segment = tape.segment(-1, 5)
    assert segment.wav[44:] == pcm(2, 3)
    assert segment.skipped == 0
